import pandas as pd
import requests
from datetime import datetime, timezone, timedelta

now = datetime.now(timezone.utc)
now_epoch = int(now.timestamp())

API_KEY = CREDENTIALS.get('FRED_API_KEY', '')
BASE = 'https://api.stlouisfed.org/fred/series/observations'

EXPECTED_COLUMNS = [
    'series_id', 'description', 'country', 'series_type',
    'latest_value', 'latest_date', 'value_30d_ago', 'change_30d',
    'change_bps', 'regime_flag', 'investment_thesis', '_epoch',
]

SERIES = [
    {'id': 'FEDFUNDS', 'desc': 'US Fed Funds Effective Rate (monthly)', 'country': 'USA', 'type': 'policy_rate'},
    {'id': 'DFEDTARU', 'desc': 'US Fed Funds Target Upper Bound', 'country': 'USA', 'type': 'policy_rate'},
    {'id': 'DGS2', 'desc': 'US 2-Year Treasury Yield', 'country': 'USA', 'type': 'short_yield'},
    {'id': 'DGS10', 'desc': 'US 10-Year Treasury Yield', 'country': 'USA', 'type': 'long_yield'},
    {'id': 'T10Y2Y', 'desc': 'US 10Y-2Y Spread', 'country': 'USA', 'type': 'yield_curve'},
    {'id': 'T10Y3M', 'desc': 'US 10Y-3M Spread (recession signal)', 'country': 'USA', 'type': 'yield_curve'},
    {'id': 'ECBDFR', 'desc': 'ECB Deposit Facility Rate', 'country': 'EUR', 'type': 'policy_rate'},
    {'id': 'IRLTLT01DEM156N', 'desc': 'Germany 10Y Government Bond', 'country': 'EUR', 'type': 'long_yield'},
    {'id': 'IRLTLT01JPM156N', 'desc': 'Japan 10Y Government Bond', 'country': 'JPN', 'type': 'long_yield'},
    {'id': 'IRLTLT01GBM156N', 'desc': 'UK 10Y Gilt', 'country': 'GBR', 'type': 'long_yield'},
]

def classify_regime(series_type, latest, change_30d):
    if latest is None:
        return 'UNKNOWN'
    if series_type == 'policy_rate':
        if change_30d is None:
            return 'STEADY'
        if change_30d > 0.1:
            return 'TIGHTENING'
        if change_30d < -0.1:
            return 'EASING'
        return 'STEADY'
    if series_type == 'yield_curve':
        if latest < 0:
            return 'INVERTED'
        if latest < 0.25:
            return 'FLAT'
        return 'NORMAL'
    if series_type == 'short_yield' or series_type == 'long_yield':
        if change_30d is None:
            return 'STABLE'
        if change_30d > 0.2:
            return 'RISING'
        if change_30d < -0.2:
            return 'FALLING'
        return 'STABLE'
    return 'UNKNOWN'

def thesis_for(series_id, regime, latest):
    if regime == 'INVERTED':
        return 'Yield-curve inversion - historical recession lead. Defensive rotation (XLU, XLP), long USD, long TLT duration'
    if regime == 'TIGHTENING':
        return 'Policy tightening - short bonds (short TLT), long USD, avoid high-multiple growth stocks'
    if regime == 'EASING':
        return 'Policy easing - long duration (TLT), risk-on rotation (cyclicals, EM)'
    if regime == 'RISING':
        return 'Long yields rising - growth-multiple compression, short TLT, short long-duration equities'
    if regime == 'FALLING':
        return 'Long yields falling - growth leadership, long TLT'
    if series_id == 'T10Y2Y' and latest is not None and latest < 0:
        return 'Curve inversion persists - recession watch continues'
    return 'Stable - track divergence vs other G10 rates for FX carry'

rows = []
for si in range(len(SERIES)):
    ent = SERIES[si]
    ser_id = ent['id']
    desc = ent['desc']
    country = ent['country']
    ser_type = ent['type']
    try:
        resp = requests.get(
            BASE,
            params={
                'series_id': ser_id,
                'api_key': API_KEY,
                'file_type': 'json',
                'sort_order': 'desc',
                'limit': 60,
            },
            timeout=30,
        )
        resp.raise_for_status()
        payload = resp.json() or {}
        obs = payload.get('observations', []) or []
    except Exception:
        continue
    values = []
    for oi in range(len(obs)):
        o = obs[oi]
        if not isinstance(o, dict):
            continue
        v = o.get('value', '.')
        if v == '.' or v is None:
            continue
        try:
            fv = float(v)
        except Exception:
            continue
        values.append({'date': str(o.get('date', '') or ''), 'value': fv})
    if not values:
        continue
    latest = values[0]['value']
    latest_date = values[0]['date']
    # Date-based 30d-ago lookup. Mixed-cadence FRED series (FEDFUNDS,
    # IRLTLT01* are monthly; DGS*, T10Y* are daily) make `idx=29` mean
    # different things - for FEDFUNDS that's ~30 MONTHS ago, producing
    # 169bp 'changes' that are really 2.5-year deltas (round-5 audit
    # surfaced this as the FEDFUNDS Δ=-169bps scale bug). Walk the
    # observations from newest to oldest and pick the first one whose
    # date is at least 30 calendar days before the latest_date.
    try:
        latest_dt = datetime.strptime(latest_date, '%Y-%m-%d')
        target_dt = latest_dt - timedelta(days=30)
    except Exception:
        latest_dt = None
        target_dt = None
    value_30d = None
    if target_dt is not None:
        for vi in range(len(values)):
            try:
                v_dt = datetime.strptime(values[vi]['date'], '%Y-%m-%d')
            except Exception:
                continue
            if v_dt <= target_dt:
                value_30d = values[vi]['value']
                break
    if value_30d is None:
        value_30d = values[-1]['value']
    change_30d = latest - value_30d
    change_bps = round(change_30d * 100.0, 2)
    regime = classify_regime(ser_type, latest, change_30d)
    thesis = thesis_for(ser_id, regime, latest)
    rows.append({
        'series_id': ser_id,
        'description': desc,
        'country': country,
        'series_type': ser_type,
        'latest_value': round(latest, 4),
        'latest_date': latest_date,
        'value_30d_ago': round(value_30d, 4),
        'change_30d': round(change_30d, 4),
        'change_bps': change_bps,
        'regime_flag': regime,
        'investment_thesis': thesis,
        '_epoch': now_epoch,
    })

if rows:
    df = pd.DataFrame(rows, columns=EXPECTED_COLUMNS)
else:
    df = pd.DataFrame(columns=EXPECTED_COLUMNS)

GENERATE_RESULTS(df)
